const updateAutoAssignment = `-- name: UpdateAutoAssignment :execrows
UPDATE photos SET
    subject_id            = $1,
    suggested_subject_id  = $2,
    assignment            = $3,
    assignment_confidence = $4,
    updated_at            = now()
WHERE id = $5 AND assignment <> 'manual'
`

type UpdateAutoAssignmentParams struct {
	SubjectID            *uuid.UUID
	SuggestedSubjectID   *uuid.UUID
	Assignment           string
	AssignmentConfidence float32
	ID                   uuid.UUID
}

// UpdateAutoAssignment never overrides a person's decision.
func (q *Queries) UpdateAutoAssignment(ctx context.Context, arg UpdateAutoAssignmentParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateAutoAssignment,
		arg.SubjectID,
		arg.SuggestedSubjectID,
		arg.Assignment,
		arg.AssignmentConfidence,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

